// ------------------------------------------------------------ type helpers

fn is_args(s: &str) -> bool {
    let t = s.trim();
    !t.is_empty() && (t.chars().all(|c| c.is_ascii_digit() || c == ',' || c == ' ') || t.eq_ignore_ascii_case("max"))
}

/// Split a column type into the type name and its length / precision:
/// `varchar(255)` → (`varchar`, `255`), `numeric(10,2)[]` → (`numeric[]`,
/// `10,2`), `timestamp(3) with time zone` → (`timestamp with time zone`,
/// `3`). Types whose parentheses hold anything else (`enum('a','b')`,
/// `Nullable(String)`) stay whole.
pub fn split_type(data_type: &str) -> (String, String) {
    let t = data_type.trim();
    let Some(open) = t.find('(') else { return (t.to_string(), String::new()) };
    let Some(close_rel) = t[open..].find(')') else { return (t.to_string(), String::new()) };
    let close = open + close_rel;
    let args = &t[open + 1..close];
    let before = t[..open].trim_end();
    let after = &t[close + 1..];
    if before.is_empty() || !is_args(args) || after.contains('(') {
        return (t.to_string(), String::new());
    }
    (format!("{before}{after}"), args.trim().to_string())
}

/// Inverse of [`split_type`]: the length goes before a trailing
/// `with time zone`, `unsigned`, `[]` ... and at the end otherwise. A type
/// that already has parentheses is used as typed.
pub fn join_type(type_text: &str, length: &str) -> String {
    let t = type_text.trim();
    let len = length.trim();
    if len.is_empty() || t.contains('(') {
        return t.to_string();
    }
    let lower = t.to_ascii_lowercase();
    let at = [" with time zone", " without time zone", " unsigned", " signed", " zerofill", "[", " array"].iter().filter_map(|s| lower.find(s)).min().unwrap_or(t.len());
    format!("{}({len}){}", &t[..at], &t[at..])
}

